/** Recette des références locales, sans assertion de livraison Figma. Propriétaire : Jonathan Kakesa. */
import {test,expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import {readFileSync,writeFileSync} from 'node:fs';
const catalogue=JSON.parse(readFileSync(new URL('../catalogue.json',import.meta.url)));
async function go(page,id){await page.goto('/#'+id);const screen=catalogue.screens.find(s=>s.id===id.split(':')[0]);if(screen)await expect(page).toHaveTitle(`${screen.title} · Référence Fluentia`);await expect(page.locator('h1')).toBeVisible();await page.evaluate(async()=>{await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});if(screen&&await page.locator('.card').count())await expect(page.locator('.card').first()).toHaveCSS('background-color',screen.universe==='Learn'?'rgb(255, 255, 255)':'rgb(16, 41, 68)');}
async function at(page,id){await expect(page).toHaveURL(new RegExp('#'+id+'$'));}
for(const width of [375,768,1440])test(`62 écrans à ${width}px`,async({page},info)=>{
 await page.setViewportSize({width,height:1000});const errors=[];page.on('pageerror',e=>errors.push(e.message));const checks=[];
 for(const s of catalogue.screens){await go(page,s.id);const geometry=await page.evaluate(()=>({innerWidth,scrollWidth:document.documentElement.scrollWidth}));expect(geometry.scrollWidth,s.id).toBeLessThanOrEqual(width);checks.push({id:s.id,...geometry});
  const overlaps=await page.locator('.grid,.index-grid').evaluateAll(grids=>grids.flatMap(grid=>{const boxes=[...grid.children].filter(n=>n.getClientRects().length).map(n=>n.getBoundingClientRect());return boxes.flatMap((a,i)=>boxes.slice(i+1).filter(b=>Math.min(a.right,b.right)-Math.max(a.left,b.left)>1&&Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top)>1));}).length);expect(overlaps,s.id+' : chevauchement de cartes').toBe(0);
  if((info.project.name==='chromium'&&['P01','A01','S01','S13','T01','E01','M01'].includes(s.id))||(info.project.name==='webkit'&&['P01','S01','S13'].includes(s.id)))await page.screenshot({path:info.outputPath(`${s.id}-${width}.png`),fullPage:true});
 }
 expect(errors).toEqual([]);writeFileSync(info.outputPath(`geometry-${width}.json`),JSON.stringify(checks,null,2));
});
for(const group of ['public','auth','student','teacher','school','admin'])test(`accessibilité à 1440px — ${group}`,async({page})=>{await page.setViewportSize({width:1440,height:1000});for(const screen of catalogue.screens.filter(s=>s.group===group)){await go(page,screen.id);expect((await new AxeBuilder({page}).analyze()).violations,screen.id).toEqual([]);}});
test('lien d’évitement au clavier',async({page})=>{await go(page,'S01');await page.keyboard.press('Tab');await expect(page.getByRole('link',{name:'Aller au contenu'})).toBeFocused();await page.keyboard.press('Enter');await expect(page.locator('#contenu')).toBeFocused();await at(page,'S01');});
test('F01 découverte, inscription, vérification, onboarding',async({page})=>{await go(page,'P01');await page.getByRole('link',{name:'Construire mon parcours'}).click();await at(page,'A01');await page.getByRole('button',{name:'Simuler l’inscription'}).click();await expect(page.locator('#form-error')).toContainText('prénom');await page.getByLabel('Prénom fictif').fill('Camille');await page.getByLabel('Courriel fictif').fill('camille@example.test');await page.getByLabel('Mot de passe fictif').fill('Fictif-2026');await page.locator('#consent').check();await page.getByRole('button',{name:'Simuler l’inscription'}).click();await at(page,'A05');await page.getByRole('link',{name:'Simuler la vérification'}).click();await at(page,'A06');await page.getByRole('button',{name:'Accéder à mon espace fictif'}).click();await at(page,'S01');});
test('F02 compréhension orale et correction',async({page})=>{await go(page,'S01');await page.getByRole('link',{name:'Commencer la séance'}).click();await at(page,'S05');await page.getByRole('button',{name:'Voir la correction'}).click();await expect(page.locator('#form-error')).toContainText('Choisissez');await page.getByLabel('Samedi matin').check();await page.getByRole('button',{name:'Voir la correction'}).click();await at(page,'S22');await expect(page.getByText('La réponse attendue dans cet exemple')).toBeVisible();});
test('F03 rédaction et feedback simulé',async({page})=>{await go(page,'S01');await page.getByRole('link',{name:'Explorer',exact:true}).nth(1).click();await at(page,'S07');await page.getByRole('button',{name:'Voir le retour simulé'}).click();await expect(page.locator('#form-error')).toContainText('cinq mots');await page.getByLabel('Votre rédaction fictive').fill('Je propose une activité de conversation à la bibliothèque samedi.');await page.getByRole('button',{name:'Voir le retour simulé'}).click();await at(page,'S23');await expect(page.getByText('Aucune analyse IA et aucune note officielle.',{exact:false})).toBeVisible();await page.getByRole('link',{name:'Revenir au brouillon'}).click();await expect(page.getByLabel('Votre rédaction fictive')).toContainText('bibliothèque');});
test('F04 studio, sept états et rapport, aucune permission audio',async({page,context})=>{await context.clearPermissions();await go(page,'S13');const names=['Commencer la simulation','État suivant','État suivant'];for(const name of names)await page.getByRole('button',{name,exact:true}).click();await expect(page.locator('#voice-status')).toHaveText('Réponse vocale simulée');await page.getByRole('button',{name:'Mettre en pause'}).click();await expect(page.locator('#voice-status')).toHaveText('Séance en pause');await page.getByRole('button',{name:'Reprendre',exact:true}).click();await page.getByRole('button',{name:'Simuler une erreur'}).click();await expect(page.locator('#voice-status')).toHaveText('Un contretemps simulé');await page.getByRole('button',{name:'Terminer',exact:true}).click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await expect(page.locator('#voice-status')).toHaveText('Séance terminée');await page.getByRole('link',{name:'Examiner le rapport fictif'}).click();await at(page,'S24');});
test('F05 examen blanc, confirmation et résultats',async({page})=>{await go(page,'S09');await page.getByRole('link',{name:'Commencer la simulation'}).click();await at(page,'S10');await page.getByLabel('Samedi matin').check();await page.getByRole('button',{name:'Terminer la simulation'}).click();await expect(page.getByRole('dialog')).toBeVisible();await page.keyboard.press('Escape');await at(page,'S10');await page.getByRole('button',{name:'Terminer la simulation'}).click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await at(page,'S11');});
test('F06 abonnement, retour focus et annulation simulée',async({page})=>{await go(page,'S19');const trigger=page.getByRole('button',{name:'Simuler un changement'});await trigger.click();await expect(page.getByRole('button',{name:'Revenir',exact:true})).toBeFocused();await page.keyboard.press('Escape');await expect(trigger).toBeFocused();await trigger.click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await expect(page.locator('#plan-badge')).toContainText('Essentiel');await page.getByRole('button',{name:'Simuler une annulation'}).click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await expect(page.locator('#plan-badge')).toContainText('Annulation simulée');});
test('F07 enseignant, classe et devoir fictif',async({page})=>{await go(page,'T01');await page.getByRole('link',{name:'Ouvrir les classes'}).click();await at(page,'T02');await page.getByRole('link',{name:'Préparer un devoir'}).click();await at(page,'T04');await page.getByRole('button',{name:'Simuler l’attribution'}).click();await expect(page.locator('#form-error')).toContainText('titre');await page.getByLabel('Titre du devoir').fill('Activité fictive');await page.getByLabel('Date indicative').fill('2026-11-10');await page.getByRole('button',{name:'Simuler l’attribution'}).click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await expect(page.locator('#notice')).toContainText('Aucun devoir réel créé');});
test('F08 administration, relecture et validation fictive',async({page})=>{await go(page,'M01');await page.getByRole('link',{name:'Ouvrir les contenus'}).click();await at(page,'M03');await page.getByRole('link',{name:'Soumettre à validation'}).click();await at(page,'M06');await page.getByRole('button',{name:'Simuler la validation'}).click();await expect(page.locator('#form-error')).toContainText('commentaire');await page.getByLabel('Commentaire de relecture').fill('Relecture fictive terminée.');await page.getByRole('button',{name:'Renvoyer au brouillon'}).click();await expect(page.locator('#approval-badge')).toContainText('brouillon');await page.getByRole('button',{name:'Simuler la validation'}).click();await page.getByRole('button',{name:'Confirmer',exact:true}).click();await expect(page.locator('#approval-badge')).toContainText('Validation simulée');});
test('états, composants, menu mobile et mouvement réduit',async({page})=>{await page.setViewportSize({width:375,height:900});for(const id of ['P01','A01','S01','S13','T01','E01','M01']){for(const state of ['loading','empty','error','forbidden','offline']){await go(page,id+':'+state);expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);}}await go(page,'components');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await go(page,'S13');await page.locator('#voice-state').selectOption('listening');expect(await page.locator('.orb').evaluate(el=>getComputedStyle(el).animationName)).toBe('none');await page.getByText('Menu',{exact:true}).click();await expect(page.getByRole('navigation',{name:'Navigation mobile'})).toBeVisible();});
